            hand.setAttribute("transform", `translate(${(t < SWEEP - 0.3 ? 400 : t < SWEEP ? 400 - 1100 * ((t - SWEEP + 0.3) / 0.3) : -700 - 2600 * swept).toFixed(1)} 0)`);
            const landed = t < NEXT - 0.2 ? -1100 : t < NEXT ? -1100 * (1 - (t - NEXT + 0.2) / 0.2) : 0;
            drop.setAttribute("transform", `translate(860 ${(772 + landed).toFixed(1)})`);
            const land = t >= NEXT && t < NEXT + 0.5 ? 0.12 * Math.exp(-(t - NEXT) * 9) : 0;
            const r = A.rng(8100 + A.boil(t));
