            C.jaw(sack.head, 0);
            label.setAttribute("opacity", t < NEXT ? 0 : 1);
            C.print("g8-defaite-label", LABEL, ((t - NEXT) / 0.3) * LABEL.length + 1);
            const s = A.shake(t, [{ at: NEXT, amp: 26 }]);
